% The status paragraph every note carries, in its own words, before any result.
% Kernel checking establishes the exact Lean proposition; it does not establish
% that the proposition is the interesting one, that it is new, or that the
% Erdős problem is closed.
\newcommand{\statusboundary}{%
  \emph{Status.}  The problem treated here is open, and this note does not
  close it.  Every statement below marked as checked is a proposition that the
  pinned Lean kernel accepts from the sources this note links to, with no
  \texttt{sorry}, no added axiom, and no unchecked evaluation.  That is a claim
  about the formal statement, not about its mathematical interest, its
  novelty, or the original problem.  The unresolved obligations are named
  exactly, in their own section, and none of the finite computations,
  reductions, or no-go results here removes one of them.
  \companionpapercontext}

% The mathematical notes remain standalone. These links supply optional
% system context without making a systems manuscript authority for a theorem.
\newcommand{\companionpapercontext}{%
  \par\smallskip\noindent\emph{Companion system context.}
  The \papersectionlink{claim-faithful-publication-systems-paper.pdf}%
  {systems-trust}{claim and trust boundary},
  \papersectionlink{cold-clone-to-proof-receipt.pdf}%
  {cold-clone-authority}{cold-clone route to proof authority}, and
  \papersectionlink{open-source-mathematics-strategy.pdf}%
  {strategy-protocol}{public contribution protocol} are described in sibling
  papers. Those descriptions do not change the mathematical status of this
  note.}

% Compact opening card for the separately stated Comparator theorem selected
% from each problem note.  The prose supplied by each note owns the
% contribution and relevance judgements; the shared final sentence states the
% mechanical assurance boundary once and points to the public evidence owner.
\newcommand{\externalreviewobject}[3]{%
  \begin{quote}\small
  \textbf{Contribution.} #1\par
  \textbf{Relation to the open problem.} #2\par
  \textbf{Executable review object.} #3  The repository's
  external-verification job compares these exact Lean propositions with
  separately declared challenge statements and an axiom budget, then asks
  Lean's kernel to check the submitted proofs.  The
  \href{https://github.com/wcook04/plectis-erdos/blob/ca0e13f8acf5ccf48506e4bdb870953d3a0856fa/formalization.yaml}%
  {formalisation manifest} and the commit-bound CI receipt record that check;
  they do not assess novelty, significance, or whether the original problem is
  solved.
  \end{quote}}

